// Software-Compliance-Pruefung
// baramundi come2gether 2026 Challenge

const items = $input.all();

// === KONFIGURATION ===
const allowed = [
  'Microsoft Office', 'Google Chrome', 'Mozilla Firefox',
  'Microsoft Teams', '7-Zip', 'Notepad++', 'Adobe Acrobat Reader',
  'Visual Studio Code', 'WinRAR'
];

const forbidden = [
  'BitTorrent', 'uTorrent', 'Vuze',
  'Steam', 'Epic Games', 'Origin',
  'TeamViewer', 'AnyDesk',
];

const required = [
  'Microsoft Office', 'Google Chrome'
];

const outdated = [
  { name: 'Java Runtime Environment', maxVersion: '8.0.400' },
  { name: 'Adobe Acrobat Reader', maxVersion: '23.008.20000' }
];

// === ANALYSE ===
const endpointMap = new Map();

for (const item of items) {
  const epId = item.json.id || item.json.endpointId;
  const epName = item.json.displayName || item.json.hostName || 'Unbekannt';
  if (!endpointMap.has(epId)) {
    endpointMap.set(epId, {
      id: epId, name: epName,
      os: item.json.operatingSystem || '-',
      software: [], violations: []
    });
  }
  if (item.json.displayName_1 || item.json.softwareName) {
    endpointMap.get(epId).software.push({
      name: item.json.displayName_1 || item.json.softwareName || '',
      version: item.json.version_1 || item.json.softwareVersion || '',
      publisher: item.json.publisher || ''
    });
  }
}

const results = [];
for (const [epId, ep] of endpointMap) {
  const swNames = ep.software.map(s => s.name);

  for (const sw of ep.software) {
    if (forbidden.some(f => sw.name.toLowerCase().includes(f.toLowerCase()))) {
      ep.violations.push({ type:'forbidden', severity:'critical', software:sw.name, version:sw.version, message:`Verbotene Software: ${sw.name}` });
    }
  }

  for (const req of required) {
    if (!swNames.some(n => n.toLowerCase().includes(req.toLowerCase()))) {
      ep.violations.push({ type:'missing', severity:'warning', software:req, version:'-', message:`Pflicht-Software fehlt: ${req}` });
    }
  }

  for (const rule of outdated) {
    const match = ep.software.find(s => s.name.toLowerCase().includes(rule.name.toLowerCase()));
    if (match && match.version <= rule.maxVersion) {
      ep.violations.push({ type:'outdated', severity:'warning', software:match.name, version:match.version, message:`Veraltete Version: ${match.name} ${match.version}` });
    }
  }

  results.push(ep);
}

const totalEndpoints = results.length;
const compliant = results.filter(r => r.violations.length === 0).length;
const withViolations = totalEndpoints - compliant;
const criticalCount = results.reduce((s, r) => s + r.violations.filter(v => v.severity === 'critical').length, 0);
const warningCount = results.reduce((s, r) => s + r.violations.filter(v => v.severity === 'warning').length, 0);

return { json: { results, stats: { totalEndpoints, compliant, withViolations, criticalCount, warningCount }, hasViolations: withViolations > 0 } };

const { results, stats } = $input.first().json;
const now = new Date().toLocaleString('de-DE', { year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit' });

const severityColors = {
  critical: { bg:'#fce4ec', border:'#c62828', text:'#c62828', label:'Kritisch' },
  warning:  { bg:'#fff8e1', border:'#f57f17', text:'#f57f17', label:'Warnung' },
  ok:       { bg:'#e8f5e9', border:'#2e7d32', text:'#2e7d32', label:'Konform' }
};

const violationRows = results.filter(ep => ep.violations.length > 0)
  .flatMap(ep => ep.violations.map(v => {
    const c = severityColors[v.severity];
    return `<tr><td style="font-weight:500;">${ep.name}</td><td>${ep.os}</td><td><span style="background:${c.bg};color:${c.text};padding:3px 10px;border-radius:4px;font-size:12px;font-weight:600;border-left:3px solid ${c.border};">${c.label}</span></td><td>${v.software}</td><td>${v.version}</td><td>${v.message}</td></tr>`;
  })).join('');

const compliantRows = results.filter(ep => ep.violations.length === 0)
  .map(ep => `<tr><td style="font-weight:500;">${ep.name}</td><td>${ep.os}</td><td><span style="background:#e8f5e9;color:#2e7d32;padding:3px 10px;border-radius:4px;font-size:12px;font-weight:600;border-left:3px solid #2e7d32;">Konform</span></td><td colspan="3" style="color:#888;">Keine Auffaelligkeiten</td></tr>`).join('');

const html = `<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><title>Software-Compliance Report</title>
<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5;padding:24px}.container{max-width:1400px;margin:0 auto;background:#fff;border-radius:10px;box-shadow:0 2px 12px rgba(0,0,0,.08);overflow:hidden}.header{background:linear-gradient(135deg,#003c71,#00a3e0);color:#fff;padding:28px 36px}.header h1{font-size:24px}.header .sub{font-size:13px;opacity:.9;margin-top:4px}.tiles{display:flex;gap:16px;flex-wrap:wrap;padding:24px 36px;background:#fafbfc;border-bottom:1px solid #e9ecef}.tile{padding:16px 20px;border-radius:6px;min-width:140px}.tile .num{font-size:28px;font-weight:700}.tile .lbl{font-size:13px;margin-top:4px}table{width:100%;border-collapse:collapse;font-size:14px}thead tr{background:#003c71;color:#fff}th{padding:12px 16px;text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.5px;font-weight:600}td{padding:10px 16px;border-bottom:1px solid #e9ecef}tbody tr:hover{background:#f8f9fa}.section{padding:24px 36px}.section h2{font-size:18px;color:#003c71;margin-bottom:16px}.footer{background:#fafbfc;padding:14px 36px;border-top:1px solid #e9ecef;font-size:12px;color:#888;text-align:center}</style></head>
<body><div class="container">
<div class="header"><h1>Software-Compliance Report</h1><div class="sub">baramundi Management Suite &mdash; ${now}</div></div>
<div class="tiles">
  <div class="tile" style="background:#003c71;color:#fff;"><div class="num">${stats.totalEndpoints}</div><div class="lbl">Endpoints</div></div>
  <div class="tile" style="background:#e8f5e9;border-left:4px solid #2e7d32;"><div class="num" style="color:#2e7d32;">${stats.compliant}</div><div class="lbl">Konform</div></div>
  <div class="tile" style="background:#fff8e1;border-left:4px solid #f57f17;"><div class="num" style="color:#f57f17;">${stats.warningCount}</div><div class="lbl">Warnungen</div></div>
  <div class="tile" style="background:#fce4ec;border-left:4px solid #c62828;"><div class="num" style="color:#c62828;">${stats.criticalCount}</div><div class="lbl">Kritisch</div></div>
</div>
<div class="section"><h2>Auffaelligkeiten</h2><div style="overflow-x:auto;"><table><thead><tr><th>Endpoint</th><th>OS</th><th>Status</th><th>Software</th><th>Version</th><th>Details</th></tr></thead><tbody>${violationRows}</tbody></table></div></div>
<div class="section"><h2>Konforme Endpoints</h2><div style="overflow-x:auto;"><table><thead><tr><th>Endpoint</th><th>OS</th><th>Status</th><th colspan="3">Details</th></tr></thead><tbody>${compliantRows}</tbody></table></div></div>
<div class="footer">baramundi come2gether 2026 Challenge &mdash; Workflow 02: Software-Compliance</div>
</div></body></html>`;

return { json: { html } };

